using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using FMODUnity;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class DiceDrawingHandler : ReferenceSingleton<DiceDrawingHandler>
{
	[Header("Spawn Animation")]
	[SerializeField]
	private AnimationCurve diceMovingCurve;

	[SerializeField]
	private float diceMovingDuration;

	[SerializeField]
	private float dice3DOrderPositionAdjustment;

	[SerializeField]
	private AnimationCurve diceCurveAnimationCurve;

	[SerializeField]
	private float diceCurveHeight;

	[SerializeField]
	private FloatReference diceRollingZPosition;

	[SerializeField]
	private float delayBeforeRolling;

	[Header("Player Assets")]
	[SerializeField]
	private ReshuffleDiscardedDicesHandler reshuffleDiscardedDicesHandler;

	[SerializeField]
	private ActionInstanceData actionInstanceData;

	[Header("Components")]
	[SerializeField]
	private TransformReference dice3DSpawnPosition;

	[SerializeField]
	private TransformReference dice3DOrderPosition;

	[SerializeField]
	private TransformReference dice3DDiscardSpawnPosition;

	[SerializeField]
	private GameObject diceInstance3DPrefab;

	[Header("Effects")]
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	[SerializeField]
	private EffectsList effectsList;

	[SerializeField]
	private CorruptedAnimalEffectsList corruptedAnimalEffectsList;

	[Header("SFX")]
	[SerializeField]
	private EventReference uiDiceDrawingToHandSFX;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[ShowNonSerializedField]
	private bool shufflingDice;

	[SerializeField]
	private List<Dice> overrideDiceDrawList = new List<Dice>();

	public bool ShufflingDice
	{
		get
		{
			return shufflingDice;
		}
		set
		{
			shufflingDice = value;
		}
	}

	public void OverrideDiceDraw(List<Dice> dicesToDraw)
	{
		overrideDiceDrawList = dicesToDraw;
	}

	public void DrawSpecificDiceFromMoreThanOnePool(List<Dice> drawSpecificDiceList, List<bool> drawFromDiscardList)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		DrawingDiceSetup();
		Debug.Log("DRAW DICE HANDLER: DrawSpecificDiceFromMoreThanOnePool");
		StartCoroutine(SpawnPlayerDice(drawSpecificDiceList, drawFromDiscardList));
	}

	public void DrawSpecificDiceFromSinglePool(List<Dice> drawSpecificDiceList, bool drawFromDiscard = false)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		DrawingDiceSetup();
		Debug.Log("DRAW DICE HANDLER: DrawSpecificDiceFromSinglePool");
		List<bool> list = new List<bool>();
		for (int i = 0; i < drawSpecificDiceList.Count; i++)
		{
			list.Add(drawFromDiscard);
		}
		StartCoroutine(SpawnPlayerDice(drawSpecificDiceList, list));
	}

	public void DrawActionCast(int amount)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		Debug.Log("DRAW DICE HANDLER: OnDrawActionCast");
		StartCoroutine(DrawingDiceCoroutine(amount));
	}

	public IEnumerator DrawingDiceCoroutine(int drawDiceActionAmount = 0)
	{
		DrawingDiceSetup();
		Debug.Log("DRAW DICE HANDLER: DrawingDiceCoroutine called");
		bool flag = drawDiceActionAmount == 0 && (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.DrawTurn || ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurnTutorial);
		if (flag)
		{
			int drawDiceAmountWithOmensModifiers = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDrawDiceAmountWithOmensModifiers();
			Debug.Log("DRAW DICE HANDLER: playerDrawPhaseDrawDiceAmount = " + drawDiceAmountWithOmensModifiers);
			if (drawDiceAmountWithOmensModifiers == 0)
			{
				ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerBoostActiveRemoveIt();
				ReferenceSingleton<PlayerDiceHandHolder>.Instance.SetDefaultDrawDicesAmount();
			}
			yield return StartCoroutine(DrawDiceNormalActionOrStartOfTurn(drawDiceAmountWithOmensModifiers, flag));
		}
		else
		{
			StartCoroutine(DrawDiceNormalActionOrStartOfTurn(drawDiceActionAmount));
		}
		EndedDrawingResetVariables();
	}

	private void DrawingDiceSetup()
	{
		ReferenceSingleton<DiceRollingHandler>.Instance.SetIsDiceRolling(value: true);
		ReferenceSingleton<GameplayHandler>.Instance.SetTimeScaleSpeedBasedOnBattleSpeed();
	}

	private void EndedDrawingResetVariables()
	{
		overrideDiceDrawList.Clear();
		shufflingDice = false;
	}

	private IEnumerator DrawDiceNormalActionOrStartOfTurn(int drawAmount, bool startOfTurnHandDiceDrawing = false)
	{
		Debug.Log("DRAW DICE HANDLER: DrawDiceNormalActionOrStartOfTurn called");
		if (drawAmount == 0)
		{
			if (startOfTurnHandDiceDrawing)
			{
				ReferenceSingleton<DiceRollingHandler>.Instance.SpawnAndRollEnemyDice();
				ReferenceSingleton<DiceRollingHandler>.Instance.SpawnAndRollCompanionDice();
			}
			yield return null;
		}
		List<Dice> tempDicePool2 = ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDices().Duplicate();
		List<Dice> diceDrawList = new List<Dice>();
		while (shufflingDice)
		{
			yield return null;
		}
		if (overrideDiceDrawList.Count > 0)
		{
			Debug.Log("DRAW DICE HANDLER: overrideDiceDrawList called.");
			diceDrawList = overrideDiceDrawList.Duplicate();
			DecreaseDiceAmountFromDrawPoolUsingDiceDrawList();
		}
		else
		{
			if (ReferenceSingleton<MiscOmensHandler>.Instance.IsSingularitySextantActiveActivateAction())
			{
				List<Dice> riskyTierDice = ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDiceFromSpecificTier(ReferenceSingleton<AssetsReference>.Instance.RiskyDieTier).Duplicate();
				int count = riskyTierDice.Count;
				if (count - drawAmount < 0)
				{
					diceDrawList.AddRange(riskyTierDice);
					tempDicePool2.RemoveAll((Dice dice) => riskyTierDice.Contains(dice));
					diceDrawList.AddRange(tempDicePool2.PickRandom(drawAmount - count, seeded: false));
				}
				else if (count - drawAmount == 0)
				{
					diceDrawList.AddRange(riskyTierDice);
				}
				else
				{
					diceDrawList = riskyTierDice.PickRandom(drawAmount, seeded: false).Duplicate();
				}
			}
			else
			{
				diceDrawList.AddRange(tempDicePool2.PickRandom(drawAmount, seeded: false).Duplicate());
			}
			int dicesAmount = ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetDicesAmount();
			int dicesAmountWithoutDiceJustPlayed = ReferenceSingleton<AssetsReference>.Instance.Discard.GetDicesAmountWithoutDiceJustPlayed();
			if (dicesAmount < drawAmount && dicesAmountWithoutDiceJustPlayed > 0)
			{
				Debug.Log("DRAW DICE HANDLER: Not enough dices on dice pool. Drawing dice pool leftovers and reshuffling discarded dices");
				ReferenceSingleton<AssetsReference>.Instance.DrawPool.ClearAllDices();
				shufflingDice = true;
				yield return reshuffleDiscardedDicesHandler.ReshuffleDices();
				shufflingDice = false;
				int count2 = tempDicePool2.Count;
				tempDicePool2 = ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDices();
				List<Dice> list = tempDicePool2.PickRandom(drawAmount - count2, seeded: false);
				for (int i = 0; i < list.Count; i++)
				{
					ReferenceSingleton<AssetsReference>.Instance.DrawPool.DecreaseDiceAmount(list[i], 1);
				}
				diceDrawList.AddRange(list);
			}
			else
			{
				Debug.Log("DRAW DICE HANDLER: Theres enough dices on dice pool. Drawing from dice pool.");
				DecreaseDiceAmountFromDrawPoolUsingDiceDrawList();
			}
		}
		if (!startOfTurnHandDiceDrawing && diceDrawList.Count == 0)
		{
			ReferenceSingleton<DiceRollingHandler>.Instance.TrySettingIsDiceRollingToFalse();
			yield break;
		}
		List<bool> list2 = new List<bool>();
		for (int j = 0; j < diceDrawList.Count; j++)
		{
			list2.Add(item: false);
		}
		yield return StartCoroutine(SpawnPlayerDice(diceDrawList, list2, startOfTurnHandDiceDrawing));
		if (startOfTurnHandDiceDrawing)
		{
			ReferenceSingleton<DiceRollingHandler>.Instance.SpawnAndRollEnemyDice();
			ReferenceSingleton<DiceRollingHandler>.Instance.SpawnAndRollCompanionDice();
		}
		void DecreaseDiceAmountFromDrawPoolUsingDiceDrawList()
		{
			for (int k = 0; k < diceDrawList.Count; k++)
			{
				ReferenceSingleton<AssetsReference>.Instance.DrawPool.DecreaseDiceAmount(diceDrawList[k], 1);
			}
		}
	}

	private IEnumerator SpawnPlayerDice(List<Dice> diceDrawList, List<bool> drawFromDiscardList, bool startOfTurnHandDiceDrawing = false)
	{
		yield return new WaitForEndOfFrame();
		Debug.LogFormat("DRAW DICE HANDLER: Player diceDrawList.Count {0}", diceDrawList.Count);
		PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		int num = component.IsPlayerDazedGetAmount();
		int num2 = 0;
		bool flag = component.IsDisoriented();
		int num3 = component.IsPlayerSuperpositionedEffectGetAmount();
		int num4 = 0;
		int num5 = component.IsPlayerCorruptedConvertGetAmount();
		int num6 = 0;
		int num7 = ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAnyWithEnemyDuskyConversionGetAmount();
		int num8 = component.IsPlayerCorruptedKnowledgeGetAmount();
		int num9 = 0;
		ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnStatusDiceDrawnOmens(diceDrawList);
		List<DiceInstance> diceToRollList = new List<DiceInstance>();
		for (int i = 0; i < diceDrawList.Count; i++)
		{
			if (diceDrawList[i] is PlayerDice)
			{
				(diceDrawList[i] as PlayerDice).DiceJustPlayed = false;
			}
			Dice dice = diceDrawList[i].InstantiateScriptableObjectTryingToCopyDiceFacesModded();
			GameObject go = ReferenceSingleton<PoolHandler>.Instance.GetObject(diceInstance3DPrefab.name, dice3DSpawnPosition.value.position);
			if (drawFromDiscardList[i])
			{
				go.transform.position = dice3DDiscardSpawnPosition.value.position;
			}
			int num10 = -1;
			for (int j = 0; j < dice.GetDiceFaces().Length; j++)
			{
				DiceFace diceFace = dice.GetDiceFaces()[j];
				if (diceFace.BattleAction is ChaoticAction && !(diceFace.BattleAction is InvokeAction))
				{
					num10 = j;
					break;
				}
			}
			if (num10 > -1)
			{
				DiceFace[] array = (dice.GetDiceFaces()[num10].BattleAction as ChaoticAction).GetRandomDice().CopyDiceFacesAsNewInstances();
				for (int k = 0; k < array.Length; k++)
				{
					DiceFace diceFace2 = dice.GetDiceFaces()[k];
					if (!(diceFace2.BattleAction is ChaoticAction))
					{
						array[k] = diceFace2;
					}
					else if (diceFace2.BattleAction is InvokeAction)
					{
						array[k] = diceFace2;
					}
				}
				dice.SetDiceFaces(array);
			}
			if (num5 > 0 && DiceHavePurifyAction(dice))
			{
				dice = playerEffectsList.CorruptedConvertEffect.ConvertCorruptPurifyIntoOppositeAction(dice);
				num5--;
				num6++;
			}
			bool flag2 = DiceHavePurifyCorruptAction(dice);
			if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.DrawTurn && num7 > 0 && flag2)
			{
				num7--;
				dice = corruptedAnimalEffectsList.DuskyConversion.ConvertCorruptPurifyIntoOppositeAction(dice);
			}
			if (num > 0 && playerEffectsList.DazedEffect.DiceHavePurifyCorruptNotRandomAction(dice))
			{
				dice = playerEffectsList.DazedEffect.TransformIntoRandomPurifyCorruptAction(dice);
				num--;
				num2++;
			}
			if (num8 > 0 && playerEffectsList.CorruptedKnowledgeEffect.DiceHaveCorruptNotAreaCorruptAction(dice))
			{
				dice = playerEffectsList.CorruptedKnowledgeEffect.TransformIntoAreaCorruptAction(dice);
				num8--;
				num9++;
			}
			if (flag)
			{
				dice = effectsList.DisorientedEffect.RandomizeValue(dice);
			}
			if (num3 > 0 && flag2)
			{
				dice = playerEffectsList.SuperpositionedEffect.ConvertCorruptPurifyIntoConfuseAction(dice);
				num3--;
				num4++;
			}
			dice.ToggleActionValueModifier(ReferenceSingleton<PlayerDiceHandHolder>.Instance.ActionValueModifiers);
			if (startOfTurnHandDiceDrawing)
			{
				Vector3 startPosition = go.transform.position;
				Vector3 vector = Vector3.left * ((float)diceDrawList.Count / (float)ReferenceSingleton<PlayerDiceHandHolder>.Instance.DefaultDrawDicesAmount - 1f);
				Vector3 vector2 = (float)ReferenceSingleton<PlayerDiceHandHolder>.Instance.DefaultDrawDicesAmount / (float)diceDrawList.Count * dice3DOrderPositionAdjustment * Vector3.right * i;
				Vector3 targetPosition = dice3DOrderPosition.value.position + vector + vector2 + Vector3.forward * diceRollingZPosition.Value;
				StartCoroutine(CoroutineUtility.CurveRoutine(diceMovingDuration, diceMovingCurve, delegate(float t, float v)
				{
					go.transform.position = Vector3.Lerp(startPosition, targetPosition, v) + Vector3.up * diceCurveHeight * diceCurveAnimationCurve.Evaluate(t);
				}));
			}
			DiceInstance componentInChildren = go.GetComponentInChildren<DiceInstance>();
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.AddDiceInstanceToHand(componentInChildren, dice);
			diceToRollList.Add(componentInChildren);
			Debug.LogFormat("DRAW DICE HANDLER: Player dicesToBeRolledAmount {0}", diceToRollList.Count);
			componentInChildren.SetOriginalDice(diceDrawList[i].InstantiateScriptableObjectTryingToCopyDiceFacesModded());
			if (ReferenceSingleton<AssetsReference>.Instance.DicePool.HasDice(diceDrawList[i]))
			{
				ReferenceSingleton<AssetsReference>.Instance.DicePool.DecreaseDiceAmount(diceDrawList[i], 1, updateDicePoolText: false);
				ReferenceSingleton<AssetsReference>.Instance.DicePool.IncreaseDiceAmount(componentInChildren.OriginalDice, 1, insertAsFirst: false, updateDicePoolText: false);
			}
			componentInChildren.Initialize(dice, actionInstanceData, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
			componentInChildren.SetupDiceToRoll();
			Debug.Log("DRAW DICE HANDLER: Spawning " + go.name);
		}
		if (num2 > 0)
		{
			component.IsPlayerDazedDecreaseEffect(num2);
		}
		if (num4 > 0)
		{
			component.IsPlayerSuperpositionedEffectDecreaseEffect(num4);
		}
		if (num6 > 0)
		{
			component.IsPlayerCorruptedConvertDecreaseEffect(num6);
		}
		if (num9 > 0)
		{
			component.IsPlayerCorruptedKnowledgeDecreaseEffect(num9);
		}
		if (startOfTurnHandDiceDrawing)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDiceDrawingToHandSFX);
			InvokeAlternatives.Invoke(this, diceMovingDuration + delayBeforeRolling, delegate
			{
				ReferenceSingleton<DiceRollingHandler>.Instance.RollDice(diceToRollList, startOfTurnHandDiceDrawing);
			});
		}
		else
		{
			ReferenceSingleton<DiceRollingHandler>.Instance.RollDice(diceToRollList);
		}
	}

	private bool DiceHavePurifyCorruptAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is PurifyAction || battleAction is CorruptAction)
			{
				return true;
			}
			if (dice.GetDiceFaces()[i].EnableSecondAction)
			{
				BattleAction secondBattleAction = dice.GetDiceFaces()[i].SecondBattleAction;
				if (secondBattleAction is PurifyAction || secondBattleAction is CorruptAction)
				{
					return true;
				}
			}
		}
		return false;
	}

	private bool DiceHavePurifyAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			if (dice.GetDiceFaces()[i].BattleAction is PurifyAction)
			{
				return true;
			}
			if (dice.GetDiceFaces()[i].EnableSecondAction && dice.GetDiceFaces()[i].SecondBattleAction is PurifyAction)
			{
				return true;
			}
		}
		return false;
	}
}
